using Microsoft.EntityFrameworkCore;using Namaa.Application.Abstractions.Persistence;using Namaa.Domain.Entities;namespace Namaa.Infrastructure.Persistence.Repositories;public sealed class InvoiceRepository(NamaaDbContext db):IInvoiceRepository{public Task<bool>ExistsByNumberAsync(string number,CancellationToken cancellationToken=default)=>db.Invoices.AsNoTracking().AnyAsync(e=>e.InvoiceNumber==number,cancellationToken);public Task<Invoice?>FindByIdAsync(long id,CancellationToken cancellationToken=default)=>db.Invoices.AsNoTracking().Include(e=>e.Items).SingleOrDefaultAsync(e=>e.Id==id,cancellationToken);public Task<Invoice?>FindForUpdateAsync(long id,CancellationToken cancellationToken=default)=>db.Invoices.Include(e=>e.Items).SingleOrDefaultAsync(e=>e.Id==id,cancellationToken);public async Task<IReadOnlyList<Invoice>>GetAllAsync(CancellationToken cancellationToken=default)=>await db.Invoices.AsNoTracking().Include(e=>e.Items).OrderByDescending(e=>e.IssueDate).ToListAsync(cancellationToken);public async Task AddAsync(Invoice entity,CancellationToken cancellationToken=default)=>await db.Invoices.AddAsync(entity,cancellationToken);}
